import SwiftUI

/// Glyphs of the official client's icon font (its shared icon library), as drawn on the video
/// page's action row: filled for the row itself, the line versions for lighter places.
/// Outlines are in font units (1000 per em), y downward from the top of the em box.
enum BiliIcon: CaseIterable, Sendable {
  case likeFill, like, dislikeFill, dislike, coinFill, coin, starFill, star, shareFill, share, downloadFill

  fileprivate static let paths: [BiliIcon: Path] = Dictionary(
    uniqueKeysWithValues: allCases.map { ($0, BiliIcon.parse($0.outline)) })

  /// M x y / L x y / Q cx cy x y / Z, numbers separated by spaces.
  private static func parse(_ text: String) -> Path {
    var path = Path()
    var numbers: [CGFloat] = []
    var command: Character = " "
    var token = ""
    func flushToken() {
      if !token.isEmpty, let v = Double(token) { numbers.append(CGFloat(v)) }
      token = ""
    }
    func run() {
      switch command {
      case "M" where numbers.count >= 2: path.move(to: CGPoint(x: numbers[0], y: numbers[1]))
      case "L" where numbers.count >= 2: path.addLine(to: CGPoint(x: numbers[0], y: numbers[1]))
      case "Q" where numbers.count >= 4:
        path.addQuadCurve(
          to: CGPoint(x: numbers[2], y: numbers[3]), control: CGPoint(x: numbers[0], y: numbers[1]))
      case "Z": path.closeSubpath()
      default: break
      }
      numbers.removeAll(keepingCapacity: true)
    }
    for ch in text {
      if ch == "M" || ch == "L" || ch == "Q" || ch == "Z" {
        flushToken(); run(); command = ch
      } else if ch == " " {
        flushToken()
      } else {
        token.append(ch)
      }
    }
    flushToken(); run()
    return path
  }

