/// One glyph, filled with the foreground style and fitted (square) into its frame.
struct BiliIconShape: Shape {
  let icon: BiliIcon
  func path(in rect: CGRect) -> Path {
    let side = min(rect.width, rect.height)
    let scale = side / 1000
    let transform = CGAffineTransform(translationX: rect.midX - side / 2, y: rect.midY - side / 2)
      .scaledBy(x: scale, y: scale)
    return (BiliIcon.paths[icon] ?? Path()).applying(transform)
  }
}
